func calculateTime(keyboard string, word string) int {
	pos := make([]int, 26)
	for i := 0; i < 26; i++ {
		pos[keyboard[i]-'a'] = i
	}
	ans, cur := 0, 0
	for i := 0; i < len(word); i++ {
		next := pos[word[i]-'a']
		d := next - cur
		if d < 0 {
			d = -d
		}
		ans += d
		cur = next
	}
	return ans
}

class Solution {
  public int calculateTime(String keyboard, String word) {
    int[] pos = new int[26];
    for (int i = 0; i < 26; i++) {
      pos[keyboard.charAt(i) - 'a'] = i;
    }
    int ans = 0, cur = 0;
    for (int i = 0; i < word.length(); i++) {
      int next = pos[word.charAt(i) - 'a'];
      ans += Math.abs(cur - next);
      cur = next;
    }
    return ans;
  }
}

class Solution:
    def calculateTime(self, keyboard: str, word: str) -> int:
        pos = {c: i for i, c in enumerate(keyboard)}
        ans = cur = 0
        for c in word:
            nxt = pos[c]
            ans += abs(cur - nxt)
            cur = nxt
        return ans

impl Solution {
  pub fn calculate_time(keyboard: String, word: String) -> i32 {
    let kb = keyboard.as_bytes();
    let mut pos = [0usize; 26];
    for i in 0..26 {
      pos[(kb[i] - b'a') as usize] = i;
    }
    let mut ans = 0i32;
    let mut cur = 0i32;
    for &c in word.as_bytes() {
      let next = pos[(c - b'a') as usize] as i32;
      ans += (cur - next).abs();
      cur = next;
    }
    ans
  }
}

const calculateTime = (keyboard: string, word: string): number => {
  const pos: Record<string, number> = {};
  for (let i = 0; i < keyboard.length; i++) pos[keyboard[i]] = i;
  let ans = 0;
  let cur = 0;
  for (const c of word) {
    const next = pos[c];
    ans += Math.abs(cur - next);
    cur = next;
  }
  return ans;
};

class Solution {
public:
  int calculateTime(string keyboard, string word) {
    unordered_map<char, int> mp;
    for (int i = 0; i < 26; i++)
      mp[keyboard[i]] = i;
    int ans = 0;
    int i = 0;
    for (char c : word) {
      ans += abs(i - mp[c]);
      i = mp[c];
    }

    return ans;
  }
};
